text:
{{
  (() => {
    const val = Get_Detail_Intervention.data[0]?.Statut || "";
    const statut = val.toUpperCase().trim();
    let emoji = "";

    switch (statut) {
      case 'À VÉRIFIER': emoji = '👁️ '; break;
      case 'PIECE A COMMANDER':
      case 'PIÈCE À COMMANDER': emoji = '🛒 '; break;
      case 'DEVIS': emoji = '📜 '; break;
      case 'EN COURS': emoji = '🛠️'; break;
      case 'EN TEST': emoji = '🧪 '; break;
      case 'TAST':
      case 'À DIAGNOSTIQUER': emoji = '🔍 '; break;
      case 'A REMONTER':
      case 'À REMONTER': emoji = '🔨 '; break;
      case 'ATTENTE CLIENT': emoji = '👨 '; break;
      case 'PIECE EN COMMANDE':
      case 'PIÈCE EN COMMANDE': emoji = '🚚 '; break;
      case 'PRÊT': emoji = '✅ '; break;
    }

    return emoji + val;
  })()
}}

textColor:
{{
  (() => {
    const statut = (Get_Detail_Intervention.data[0]?.Statut || "").toUpperCase().trim();
    switch (statut) {
      case 'PIECE A COMMANDER':
      case 'PIÈCE À COMMANDER': return '#dc2626'; // Rouge
      case 'PIECE EN COMMANDE':
      case 'PIÈCE EN COMMANDE': return '#16a34a'; // Vert
      case 'DEVIS': return '#9333ea'; // Violet
      case 'A REMONTER':
      case 'À REMONTER': return '#ea580c'; // Orange / Rouge
      case 'À DIAGNOSTIQUER': return '#2563eb'; // Bleu
      case 'PRÊT': return '#15803d'; // Vert foncé
      default: return '#0f172a'; // Couleur texte sombre par défaut
    }
  })()
}}
